int spec_has_method(String cls, String method) {
    const SpecClassMeta* m = spec_class_find(spec_buf_to_cstring(cls));
    return spec_class_find_method(m, spec_buf_to_cstring(method)) ? 1 : 0;
}

void* spec_instantiate(String cls) {
    const SpecClassMeta* m = spec_class_find(spec_buf_to_cstring(cls));
    if (!m) spec_panic("Introspection:instantiate — unknown class");
    if (!m->construct) spec_panic("Introspection:instantiate — class init requires arguments");
    return m->construct();
}

void spec_invoke_void_by_name(void* instance, String method) {
    if (!instance) spec_panic("Introspection:invoke on a null instance");
    const char* tn = *((const char**)instance);
    const SpecClassMeta* m = spec_class_find(tn);
    if (!m) spec_panic("Introspection:invoke — instance of an unregistered class");
    const SpecMethodMeta* mm = spec_class_find_method(m, spec_buf_to_cstring(method));
    if (!mm) spec_panic("Introspection:invoke — no such method");
    spec_invoke_void_by_meta(instance, mm);
}

long long spec_clock_ms(void) {
    return spec_pal_get_wall_time_us() / 1000;
}

long long spec_time_monotonic_ns(void) {
#if defined(_WIN32)
    LARGE_INTEGER freq, count;
    if (QueryPerformanceFrequency(&freq) && QueryPerformanceCounter(&count) && freq.QuadPart > 0) {
        long long whole = count.QuadPart / freq.QuadPart;
        long long rem = count.QuadPart % freq.QuadPart;
        return whole * 1000000000LL + (rem * 1000000000LL) / freq.QuadPart;
    }
    return 0;
#else
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ((long long)ts.tv_sec * 1000000000LL) + (long long)ts.tv_nsec;
#endif
}

long long spec_time_monotonic_us(void) {
    return spec_time_monotonic_ns() / 1000LL;
}

long long spec_time_monotonic_ms(void) {
    return spec_time_monotonic_ns() / 1000000LL;
}

long long spec_time_epoch_ns(void) {
#if defined(_WIN32)
    FILETIME ft;
    GetSystemTimeAsFileTime(&ft);
    ULARGE_INTEGER uli;
    uli.LowPart = ft.dwLowDateTime;
    uli.HighPart = ft.dwHighDateTime;
    if (uli.QuadPart < 116444736000000000ULL) return 0;
    return (long long)((uli.QuadPart - 116444736000000000ULL) * 100ULL);
#else
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return ((long long)ts.tv_sec * 1000000000LL) + (long long)ts.tv_nsec;
#endif
}

long long spec_time_epoch_ms(void) {
    return spec_time_epoch_ns() / 1000000LL;
}

void spec_time_sleep_ns(long long ns) {
    if (ns <= 0) return;
#if defined(_WIN32)
    long long target = spec_time_monotonic_ns() + ns;
    long long ms = ns / 1000000LL;
    if (ms > 1) {
        Sleep((DWORD)(ms - 1));
    }
    while (spec_time_monotonic_ns() < target) {
        Sleep(0);
    }
#else
    struct timespec ts;
    ts.tv_sec = ns / 1000000000LL;
    ts.tv_nsec = ns % 1000000000LL;
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
    }
#endif
}

void spec_time_sleep_us(long long us) {
    if (us <= 0) return;
    spec_time_sleep_ns(us * 1000LL);
}

void spec_time_sleep_ms(long long ms) {
    if (ms <= 0) return;
    spec_time_sleep_ns(ms * 1000000LL);
}

static long long spec_days_from_civil_c(long long y, long long m, long long d) {
    y -= (m <= 2);
    long long era = (y >= 0 ? y : y - 399) / 400;
    long long yoe = y - era * 400;
    long long doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
    long long doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    return era * 146097 + doe - 719468;
}

long long spec_time_local_offset_sec(long long epoch_sec) {
    struct tm local_tm, utc_tm;
#if defined(_WIN32)
    __time64_t t = (__time64_t)epoch_sec;
    if (_localtime64_s(&local_tm, &t) != 0) return 0;
    if (_gmtime64_s(&utc_tm, &t) != 0) return 0;
#else
    time_t t = (time_t)epoch_sec;
    if (!localtime_r(&t, &local_tm)) return 0;
    if (!gmtime_r(&t, &utc_tm)) return 0;
#endif
    long long local_days = spec_days_from_civil_c((long long)local_tm.tm_year + 1900, (long long)local_tm.tm_mon + 1, (long long)local_tm.tm_mday);
    long long utc_days = spec_days_from_civil_c((long long)utc_tm.tm_year + 1900, (long long)utc_tm.tm_mon + 1, (long long)utc_tm.tm_mday);
    long long local_sec = local_days * 86400LL + (long long)local_tm.tm_hour * 3600LL + (long long)local_tm.tm_min * 60LL + (long long)local_tm.tm_sec;
    long long utc_sec = utc_days * 86400LL + (long long)utc_tm.tm_hour * 3600LL + (long long)utc_tm.tm_min * 60LL + (long long)utc_tm.tm_sec;
    return local_sec - utc_sec;
}

typedef struct SpecTimerTask {
    long long id;
    long long interval_ns;
    long long count;
    SpecClosure* callback;
    bool cancelled;
    struct SpecTimerTask* next;
} SpecTimerTask;

static pthread_mutex_t _spec_timer_mutex = PTHREAD_MUTEX_INITIALIZER;
static SpecTimerTask* _spec_timer_head = NULL;
static long long _spec_next_timer_id = 0;

static void* spec_timer_worker(void* arg) {
    SpecTimerTask* task = (SpecTimerTask*)arg;
    long long target_ns = spec_time_monotonic_ns() + task->interval_ns;
    long long executed = 0;
    while (task->count <= 0 || executed < task->count) {
        for (;;) {
            pthread_mutex_lock(&_spec_timer_mutex);
            bool is_cancelled = task->cancelled;
            pthread_mutex_unlock(&_spec_timer_mutex);
            if (is_cancelled) goto done;
            long long now_ns = spec_time_monotonic_ns();
            long long rem_ns = target_ns - now_ns;
            if (rem_ns <= 0) break;
            long long chunk_ns = rem_ns > 20000000LL ? 20000000LL : rem_ns;
            spec_time_sleep_ns(chunk_ns);
        }
        pthread_mutex_lock(&_spec_timer_mutex);
        bool is_cancelled = task->cancelled;
        pthread_mutex_unlock(&_spec_timer_mutex);
        if (is_cancelled) break;
        if (task->callback) {
            spec_call_closure_0(task->callback);
        }
        executed++;
        target_ns += task->interval_ns;
    }
done:
    pthread_mutex_lock(&_spec_timer_mutex);
    SpecTimerTask** cur = &_spec_timer_head;
    while (*cur) {
        if (*cur == task) {
            *cur = task->next;
            break;
        }
        cur = &(*cur)->next;
    }
    pthread_mutex_unlock(&_spec_timer_mutex);
    if (task->callback) spec_release(task->callback);
    free(task);
    spec_async_task_finished();
    return NULL;
}

long long spec_time_set_interval(long long ms, long long count, SpecClosure* callback) {
    SpecTimerTask* task = (SpecTimerTask*)spec_xmalloc(sizeof(SpecTimerTask));
    task->interval_ns = (ms > 0 ? ms : 0) * 1000000LL;
    task->count = count;
    task->callback = callback ? (SpecClosure*)spec_retain(callback) : NULL;
    task->cancelled = false;
    pthread_mutex_lock(&_spec_timer_mutex);
    task->id = ++_spec_next_timer_id;
    task->next = _spec_timer_head;
    _spec_timer_head = task;
    pthread_mutex_unlock(&_spec_timer_mutex);
    spec_async_task_started();
    pthread_t tid;
    if (pthread_create(&tid, NULL, spec_timer_worker, task) != 0) {
        spec_timer_worker(task);
        return task->id;
    }
    pthread_detach(tid);
    return task->id;
}

long long spec_time_set_timeout(long long ms, SpecClosure* callback) {
    return spec_time_set_interval(ms, 1, callback);
}

bool spec_time_cancel_timer(long long timer_id) {
    pthread_mutex_lock(&_spec_timer_mutex);
    SpecTimerTask* cur = _spec_timer_head;
    bool found = false;
    while (cur) {
        if (cur->id == timer_id) {
            cur->cancelled = true;
            found = true;
            break;
        }
        cur = cur->next;
    }
    pthread_mutex_unlock(&_spec_timer_mutex);
    return found;
}

long long spec_mem_peak_kb(void) {
    return spec_pal_get_peak_rss_kb();
}

long long spec_thread_count(void) {
    return spec_pal_get_cpu_count();
}

long long spec_monitor_avg_cpu_pct(void) {
    if (_spec_mon_total_wall_us <= 0) return 0;
    return (_spec_mon_total_cpu_us * 100) / _spec_mon_total_wall_us;
}

long long spec_monitor_peak_cpu_pct(void) {
    return _spec_mon_peak_cpu_pct;
}

long long spec_monitor_avg_mem_kb(void) {
    long long count = _spec_mon_sample_count;
    if (count <= 0) return _spec_mon_peak_mem_kb;
    return _spec_mon_mem_sum_kb / count;
}

long long spec_monitor_peak_mem_kb(void) {
    return _spec_mon_peak_mem_kb;
}

void spec_monitor_start(void) {
    if (_spec_mon_active) return;
    _spec_mon_sample_count = 0;
    _spec_mon_mem_sum_kb = 0;
    _spec_mon_peak_mem_kb = 0;
    _spec_mon_peak_cpu_pct = 0;

    _spec_mon_start_wall_us = spec_pal_get_wall_time_us();
    _spec_mon_start_cpu_us = spec_pal_get_cpu_time_us();

    _spec_mon_active = true;
    spec_thread_enter();
    pthread_create(&_spec_mon_thread, NULL, _spec_monitor_worker, NULL);
}

void spec_monitor_stop(void) {
    if (!_spec_mon_active) return;
    _spec_mon_active = false;
    pthread_join(_spec_mon_thread, NULL);
    spec_thread_leave();

    long long end_wall_us = spec_pal_get_wall_time_us();
    long long end_cpu_us = spec_pal_get_cpu_time_us();

    _spec_mon_total_wall_us = end_wall_us - _spec_mon_start_wall_us;
    _spec_mon_total_cpu_us = end_cpu_us - _spec_mon_start_cpu_us;

    long long peak_ru = spec_pal_get_peak_rss_kb();
    if (peak_ru > _spec_mon_peak_mem_kb) {
        _spec_mon_peak_mem_kb = peak_ru;
    }
    long long avg_cpu = spec_monitor_avg_cpu_pct();
    if (avg_cpu > _spec_mon_peak_cpu_pct) {
        _spec_mon_peak_cpu_pct = avg_cpu;
    }
}

void spec_error_line(String s) {
    const char* cs = s ? spec_buf_to_cstring((SpecBuf*)s) : "";
    fprintf(stderr, "%s\n", cs);
}

void spec_print_line(String s) {
    printf("%s\n", s ? spec_buf_to_cstring((SpecBuf*)s) : "");
}

void spec_print(String s) {
    printf("%s", s ? spec_buf_to_cstring((SpecBuf*)s) : "");
    fflush(stdout);
}

void spec_read_line(SpecClosure* on_line) {
#if defined(_WIN32)
    char buf[4096];
    if (fgets(buf, sizeof(buf), stdin)) {
        size_t len = strlen(buf);
        while (len > 0 && (buf[len - 1] == '\n' || buf[len - 1] == '\r')) {
            buf[len - 1] = '\0';
            len--;
        }
        String text = spec_string_from_chars(buf);
        spec_call_closure_str(on_line, text);
        spec_release(text);
    }
#else
    char* _line = NULL;
    size_t _cap = 0;
    ssize_t _n = getline(&_line, &_cap, stdin);
    if (_n >= 0) {
        if (_n > 0 && _line[_n - 1] == '\n') _line[_n - 1] = '\0';
        String text = spec_string_from_chars(_line);
        spec_call_closure_str(on_line, text);
        spec_release(text);
    }
    free(_line);
#endif
}

String spec_read_bytes(long long count) {
    if (count <= 0) return spec_string_from_bytes("", 0);
    size_t want = (size_t)count;
    char* buf = (char*)spec_xmalloc(want);
    size_t got = 0;
    while (got < want) {
        size_t n = fread(buf + got, 1, want - got, stdin);
        if (n == 0) break;
        got += n;
    }
    String res = spec_string_from_bytes(buf, got);
    free(buf);
    return res;
}

void spec_console_binary_mode(void) {
#if defined(_WIN32)
    _setmode(_fileno(stdin), _O_BINARY);
    _setmode(_fileno(stdout), _O_BINARY);
#endif
}

static inline void _spec_emit_last_sock_error(SpecClosure* on_error, const char* fallback) {
    if (!on_error || !on_error->fn) return;
#if defined(_WIN32)
    int err = WSAGetLastError();
    if (err != 0) {
        char ebuf[64];
        snprintf(ebuf, sizeof(ebuf), "Socket error: WSA error %d", err);
        _spec_emit_str_error(on_error, ebuf);
        return;
    }
#else
    if (errno != 0) {
        _spec_emit_str_error(on_error, strerror(errno));
        return;
    }
#endif
    _spec_emit_str_error(on_error, fallback ? fallback : "Socket error");
}

long long spec_tcp_connect_cb(String host, long long port, long long timeout_ms, SpecClosure* on_error) {
    if (!host || port <= 0 || port > 65535) {
        _spec_emit_str_error(on_error, "Socket error: Invalid host or port");
        return -1;
    }
#if defined(_WIN32)
    _spec_ensure_winsock();
#endif
    char port_str[16];
    snprintf(port_str, sizeof(port_str), "%lld", port);
    const char* h = spec_buf_to_cstring((SpecBuf*)host);

    struct addrinfo hints, *res = NULL, *rp = NULL;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int gai_rc = getaddrinfo(h, port_str, &hints, &res);
    if (gai_rc != 0 || !res) {
#if defined(_WIN32)
        char ebuf[96];
        snprintf(ebuf, sizeof(ebuf), "Socket error: getaddrinfo failed (%d)", gai_rc);
        _spec_emit_str_error(on_error, ebuf);
#else
        _spec_emit_str_error(on_error, gai_strerror(gai_rc));
#endif
        return -1;
    }

    long long sock_fd = -1;
    int last_err = 0;
    for (rp = res; rp != NULL; rp = rp->ai_next) {
#if defined(_WIN32)
        SOCKET s = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (s == INVALID_SOCKET) { last_err = WSAGetLastError(); continue; }
        if (timeout_ms > 0) {
            DWORD tv = (DWORD)timeout_ms;
            setsockopt(s, SOL_SOCKET, SO_RCVTIMEO, (const char*)&tv, sizeof(tv));
            setsockopt(s, SOL_SOCKET, SO_SNDTIMEO, (const char*)&tv, sizeof(tv));
        }
        if (connect(s, rp->ai_addr, (int)rp->ai_addrlen) == 0) {
            sock_fd = (long long)s;
            break;
        }
        last_err = WSAGetLastError();
        closesocket(s);
#else
        int s = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (s < 0) { last_err = errno; continue; }
        if (timeout_ms > 0) {
            struct timeval tv;
            tv.tv_sec = timeout_ms / 1000;
            tv.tv_usec = (timeout_ms % 1000) * 1000;
            setsockopt(s, SOL_SOCKET, SO_RCVTIMEO, (const void*)&tv, sizeof(tv));
            setsockopt(s, SOL_SOCKET, SO_SNDTIMEO, (const void*)&tv, sizeof(tv));
        }
        if (connect(s, rp->ai_addr, rp->ai_addrlen) == 0) {
            sock_fd = (long long)s;
            break;
        }
        last_err = errno;
        close(s);
#endif
    }
    freeaddrinfo(res);
    if (sock_fd < 0) {
#if defined(_WIN32)
        char ebuf[64];
        snprintf(ebuf, sizeof(ebuf), "Socket error: WSA error %d", last_err);
        _spec_emit_str_error(on_error, ebuf);
#else
        _spec_emit_str_error(on_error, last_err != 0 ? strerror(last_err) : "Socket error: Connection failed");
#endif
    }
    return sock_fd;
}

long long spec_tcp_connect(String host, long long port, long long timeout_ms) {
    return spec_tcp_connect_cb(host, port, timeout_ms, NULL);
}

long long spec_tcp_listen_cb(String host, long long port, long long backlog, SpecClosure* on_error) {
    if (port <= 0 || port > 65535) {
        _spec_emit_str_error(on_error, "Socket error: Invalid port");
        return -1;
    }
#if defined(_WIN32)
    _spec_ensure_winsock();
#endif
    char port_str[16];
    snprintf(port_str, sizeof(port_str), "%lld", port);
    const char* h = (host && host->length > 0) ? spec_buf_to_cstring((SpecBuf*)host) : NULL;

    struct addrinfo hints, *res = NULL;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags = AI_PASSIVE;

    int gai_rc = getaddrinfo(h, port_str, &hints, &res);
    if (gai_rc != 0 || !res) {
#if defined(_WIN32)
        char ebuf[96];
        snprintf(ebuf, sizeof(ebuf), "Socket error: getaddrinfo failed (%d)", gai_rc);
        _spec_emit_str_error(on_error, ebuf);
#else
        _spec_emit_str_error(on_error, gai_strerror(gai_rc));
#endif
        return -1;
    }

#if defined(_WIN32)
    SOCKET s = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (s == INVALID_SOCKET) { _spec_emit_last_sock_error(on_error, "Socket error: socket() failed"); freeaddrinfo(res); return -1; }
    BOOL opt = TRUE;
    setsockopt(s, SOL_SOCKET, SO_REUSEADDR, (const char*)&opt, sizeof(opt));
    if (bind(s, res->ai_addr, (int)res->ai_addrlen) != 0 || listen(s, backlog > 0 ? (int)backlog : 128) != 0) {
        _spec_emit_last_sock_error(on_error, "Socket error: bind/listen failed");
        closesocket(s);
        freeaddrinfo(res);
        return -1;
    }
    freeaddrinfo(res);
    return (long long)s;
#else
    int s = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (s < 0) { _spec_emit_last_sock_error(on_error, "Socket error: socket() failed"); freeaddrinfo(res); return -1; }
    int opt = 1;
    setsockopt(s, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    if (bind(s, res->ai_addr, res->ai_addrlen) != 0 || listen(s, backlog > 0 ? (int)backlog : 128) != 0) {
        _spec_emit_last_sock_error(on_error, "Socket error: bind/listen failed");
        close(s);
        freeaddrinfo(res);
        return -1;
    }
    freeaddrinfo(res);
    return (long long)s;
#endif
}

long long spec_tcp_listen(String host, long long port, long long backlog) {
    return spec_tcp_listen_cb(host, port, backlog, NULL);
}

long long spec_socket_accept_cb(long long fd, SpecClosure* on_error) {
    if (fd < 0) {
        _spec_emit_str_error(on_error, "Socket error: Socket is closed or invalid");
        return -1;
    }
#if defined(_WIN32)
    SOCKET s = accept((SOCKET)fd, NULL, NULL);
    if (s == INVALID_SOCKET) {
        _spec_emit_last_sock_error(on_error, "Socket error: accept() failed");
        return -1;
    }
    return (long long)s;
#else
    int s = accept((int)fd, NULL, NULL);
    if (s < 0) {
        _spec_emit_last_sock_error(on_error, "Socket error: accept() failed");
    }
    return (long long)s;
#endif
}

long long spec_socket_accept(long long fd) {
    return spec_socket_accept_cb(fd, NULL);
}

long long spec_socket_send_cb(long long fd, SpecByteBuffer* buf, SpecClosure* on_error) {
    if (fd < 0) {
        _spec_emit_str_error(on_error, "Socket error: Socket is closed or invalid");
        return -1;
    }
    if (!buf || buf->length == 0) return 0;
#if defined(_WIN32)
    int n = send((SOCKET)fd, (const char*)buf->data, (int)buf->length, 0);
    if (n == SOCKET_ERROR) {
        _spec_emit_last_sock_error(on_error, "Socket error: send() failed");
        return -1;
    }
    return (long long)n;
#else
    ssize_t n = send((int)fd, buf->data, buf->length, 0);
    if (n < 0) {
        _spec_emit_last_sock_error(on_error, "Socket error: send() failed");
        return -1;
    }
    return (long long)n;
#endif
}

long long spec_socket_send(long long fd, SpecByteBuffer* buf) {
    return spec_socket_send_cb(fd, buf, NULL);
}

long long spec_socket_send_str_cb(long long fd, String str, SpecClosure* on_error) {
    if (fd < 0) {
        _spec_emit_str_error(on_error, "Socket error: Socket is closed or invalid");
        return -1;
    }
    if (!str || str->length == 0) return 0;
    const char* cs = spec_buf_to_cstring((SpecBuf*)str);
    size_t len = strlen(cs);
#if defined(_WIN32)
    int n = send((SOCKET)fd, cs, (int)len, 0);
    if (n == SOCKET_ERROR) {
        _spec_emit_last_sock_error(on_error, "Socket error: send() failed");
        return -1;
    }
    return (long long)n;
#else
    ssize_t n = send((int)fd, cs, len, 0);
    if (n < 0) {
        _spec_emit_last_sock_error(on_error, "Socket error: send() failed");
        return -1;
    }
    return (long long)n;
#endif
}

long long spec_socket_send_str(long long fd, String str) {
    return spec_socket_send_str_cb(fd, str, NULL);
}

SpecByteBuffer* spec_socket_recv_cb(long long fd, long long max_bytes, SpecClosure* on_error) {
    if (fd < 0) {
        _spec_emit_str_error(on_error, "Socket error: Socket is closed or invalid");
        return NULL;
    }
    if (max_bytes <= 0) max_bytes = 4096;
    if (max_bytes > 1048576) max_bytes = 1048576;

    SpecByteBuffer* b = spec_bytebuffer_new();
    b->data = (unsigned char*)spec_xmalloc((size_t)max_bytes);
    b->capacity = (size_t)max_bytes;

#if defined(_WIN32)
    int n = recv((SOCKET)fd, (char*)b->data, (int)max_bytes, 0);
    if (n <= 0) {
        if (n == 0) { b->length = 0; return b; }
        _spec_emit_last_sock_error(on_error, "Socket error: recv() failed");
        spec_release(b);
        return NULL;
    }
    b->length = (size_t)n;
    return b;
#else
    ssize_t n = recv((int)fd, b->data, (size_t)max_bytes, 0);
    if (n <= 0) {
        if (n == 0) { b->length = 0; return b; }
        _spec_emit_last_sock_error(on_error, "Socket error: recv() failed");
        spec_release(b);
        return NULL;
    }
    b->length = (size_t)n;
    return b;
#endif
}

SpecByteBuffer* spec_socket_recv(long long fd, long long max_bytes) {
    return spec_socket_recv_cb(fd, max_bytes, NULL);
}

String spec_socket_recv_str_cb(long long fd, long long max_bytes, SpecClosure* on_error) {
    SpecByteBuffer* b = spec_socket_recv_cb(fd, max_bytes, on_error);
    if (!b) return spec_string_intern("");
    String s = spec_bytebuffer_to_string(b);
    spec_release(b);
    return s;
}

String spec_socket_recv_str(long long fd, long long max_bytes) {
    return spec_socket_recv_str_cb(fd, max_bytes, NULL);
}

long long spec_socket_close(long long fd) {
    if (fd < 0) return 0;
#if defined(_WIN32)
    closesocket((SOCKET)fd);
#else
    close((int)fd);
#endif
    return 0;
}

long long spec_socket_poll(long long fd, long long mode, long long timeout_ms) {
    if (fd < 0) return -1;
#if defined(_WIN32)
    WSAPOLLFD pfd;
    pfd.fd = (SOCKET)fd;
    pfd.events = 0;
    if (mode & 1) pfd.events |= POLLIN;
    if (mode & 2) pfd.events |= POLLOUT;
    pfd.revents = 0;
    int ret = WSAPoll(&pfd, 1, (INT)timeout_ms);
    if (ret > 0) return (pfd.revents & (POLLIN | POLLOUT)) ? 1 : 0;
    return (ret == 0) ? 0 : -1;
#else
    struct pollfd pfd;
    pfd.fd = (int)fd;
    pfd.events = 0;
    if (mode & 1) pfd.events |= POLLIN;
    if (mode & 2) pfd.events |= POLLOUT;
    pfd.revents = 0;
    int ret = poll(&pfd, 1, (int)timeout_ms);
    if (ret > 0) return (pfd.revents & (POLLIN | POLLOUT)) ? 1 : 0;
    return (ret == 0) ? 0 : -1;
#endif
}

long long spec_socket_set_timeout(long long fd, long long timeout_ms) {
    if (fd < 0) return -1;
#if defined(_WIN32)
    DWORD tv = (timeout_ms > 0) ? (DWORD)timeout_ms : 0;
    setsockopt((SOCKET)fd, SOL_SOCKET, SO_RCVTIMEO, (const char*)&tv, sizeof(tv));
    setsockopt((SOCKET)fd, SOL_SOCKET, SO_SNDTIMEO, (const char*)&tv, sizeof(tv));
#else
    struct timeval tv;
    tv.tv_sec = timeout_ms / 1000;
    tv.tv_usec = (timeout_ms % 1000) * 1000;
    setsockopt((int)fd, SOL_SOCKET, SO_RCVTIMEO, (const void*)&tv, sizeof(tv));
    setsockopt((int)fd, SOL_SOCKET, SO_SNDTIMEO, (const void*)&tv, sizeof(tv));
#endif
    return 0;
}

long long spec_audio_open_cb(long long sample_rate, long long channels, long long format, SpecClosure* on_error) {
    if (sample_rate <= 0) sample_rate = 44100;
    if (channels <= 0) channels = 2;
    if (format <= 0) format = 1;

    int slot = -1;
    for (int i = 0; i < 8; i++) {
        if (!_spec_audio_streams[i].active) {
            slot = i;
            break;
        }
    }
    if (slot < 0) {
        _spec_emit_str_error(on_error, "Audio error: Maximum concurrent audio streams reached");
        return -1;
    }

#if defined(__linux__)
    if (!_spec_init_alsa()) {
        _spec_emit_str_error(on_error, "Audio error: Failed to initialize ALSA");
        return -1;
    }
    spec_snd_pcm_t* pcm = NULL;
    if (_spec_snd_pcm_open(&pcm, "default", 0, 0) != 0) {
        _spec_emit_str_error(on_error, "Audio error: Failed to open ALSA PCM device");
        return -1;
    }
    if (_spec_snd_pcm_set_params(pcm, 2 /* S16_LE */, 3 /* RW_INTERLEAVED */, (unsigned int)channels, (unsigned int)sample_rate, 1, 500000) != 0) {
        if (_spec_snd_pcm_close) _spec_snd_pcm_close(pcm);
        _spec_emit_str_error(on_error, "Audio error: Failed to configure ALSA PCM parameters");
        return -1;
    }
    _spec_audio_streams[slot].alsa_handle = pcm;
#elif defined(_WIN32)
    if (!_spec_init_winmm()) {
        _spec_emit_str_error(on_error, "Audio error: Failed to initialize WinMM");
        return -1;
    }
    WAVEFORMATEX wfx;
    memset(&wfx, 0, sizeof(wfx));
    wfx.wFormatTag = WAVE_FORMAT_PCM;
    wfx.nChannels = (WORD)channels;
    wfx.nSamplesPerSec = (DWORD)sample_rate;
    wfx.wBitsPerSample = 16;
    wfx.nBlockAlign = (WORD)(channels * 2);
    wfx.nAvgBytesPerSec = (DWORD)(sample_rate * wfx.nBlockAlign);
    HWAVEOUT hWave = NULL;
    if (_spec_waveOutOpen(&hWave, WAVE_MAPPER, &wfx, 0, 0, CALLBACK_NULL) != MMSYSERR_NOERROR) {
        _spec_emit_str_error(on_error, "Audio error: waveOutOpen failed");
        return -1;
    }
    _spec_audio_streams[slot].h_wave_out = hWave;
#elif defined(__APPLE__) && defined(__MACH__)
    if (!_spec_init_audiotoolbox()) {
        _spec_emit_str_error(on_error, "Audio error: Failed to initialize AudioToolbox");
        return -1;
    }
    AudioStreamBasicDescription desc;
    memset(&desc, 0, sizeof(desc));
    desc.mSampleRate = (Float64)sample_rate;
    desc.mFormatID = kAudioFormatLinearPCM;
    desc.mFormatFlags = kLinearPCMFormatFlagIsSignedInteger | kAudioFormatFlagIsPacked;
    desc.mBytesPerPacket = (UInt32)(channels * 2);
    desc.mFramesPerPacket = 1;
    desc.mBytesPerFrame = (UInt32)(channels * 2);
    desc.mChannelsPerFrame = (UInt32)channels;
    desc.mBitsPerChannel = 16;
    AudioQueueRef queue = NULL;
    if (_spec_AudioQueueNewOutput(&desc, _spec_audio_queue_cb, NULL, NULL, NULL, 0, &queue) != noErr) {
        _spec_emit_str_error(on_error, "Audio error: AudioQueueNewOutput failed");
        return -1;
    }
    _spec_AudioQueueStart(queue, NULL);
    _spec_audio_streams[slot].aq_queue = queue;
#endif

    _spec_audio_streams[slot].active = true;
    _spec_audio_streams[slot].sample_rate = sample_rate;
    _spec_audio_streams[slot].channels = channels;
    _spec_audio_streams[slot].format = format;
    return (long long)(slot + 1);
}

long long spec_audio_open(long long sample_rate, long long channels, long long format) {
    return spec_audio_open_cb(sample_rate, channels, format, NULL);
}

long long spec_audio_write_cb(long long handle, SpecByteBuffer* buf, SpecClosure* on_error) {
    long long idx = handle - 1;
    if (idx < 0 || idx >= 8 || !_spec_audio_streams[idx].active) {
        _spec_emit_str_error(on_error, "Audio error: Audio stream is closed or invalid");
        return -1;
    }
    if (!buf || buf->length == 0) return 0;
#if defined(__linux__)
    if (!_spec_snd_pcm_writei) {
        _spec_emit_str_error(on_error, "Audio error: ALSA write function unavailable");
        return -1;
    }
    long long bytes_per_frame = _spec_audio_streams[idx].channels * 2;
    unsigned long frames = (unsigned long)(buf->length / bytes_per_frame);
    long res = _spec_snd_pcm_writei((spec_snd_pcm_t*)_spec_audio_streams[idx].alsa_handle, buf->data, frames);
    if (res < 0) {
        if (_spec_snd_pcm_recover) res = _spec_snd_pcm_recover((spec_snd_pcm_t*)_spec_audio_streams[idx].alsa_handle, (int)res, 0);
        if (res == 0) res = _spec_snd_pcm_writei((spec_snd_pcm_t*)_spec_audio_streams[idx].alsa_handle, buf->data, frames);
    }
    if (res < 0) {
        _spec_emit_str_error(on_error, "Audio error: Failed to write ALSA audio samples");
        return res;
    }
    return (long long)(res * bytes_per_frame);
#elif defined(_WIN32)
    HWAVEOUT hWave = _spec_audio_streams[idx].h_wave_out;
    WAVEHDR* hdr = (WAVEHDR*)spec_xmalloc(sizeof(WAVEHDR));
    memset(hdr, 0, sizeof(WAVEHDR));
    hdr->lpData = (LPSTR)spec_xmalloc(buf->length);
    memcpy(hdr->lpData, buf->data, buf->length);
    hdr->dwBufferLength = (DWORD)buf->length;
    if (_spec_waveOutPrepareHeader) _spec_waveOutPrepareHeader(hWave, hdr, sizeof(WAVEHDR));
    if (_spec_waveOutWrite) _spec_waveOutWrite(hWave, hdr, sizeof(WAVEHDR));
    return (long long)buf->length;
#elif defined(__APPLE__) && defined(__MACH__)
    AudioQueueRef queue = _spec_audio_streams[idx].aq_queue;
    AudioQueueBufferRef buffer = NULL;
    if (_spec_AudioQueueAllocateBuffer && _spec_AudioQueueAllocateBuffer(queue, (UInt32)buf->length, &buffer) == noErr) {
        memcpy(buffer->mAudioData, buf->data, buf->length);
        buffer->mAudioDataByteSize = (UInt32)buf->length;
        if (_spec_AudioQueueEnqueueBuffer) _spec_AudioQueueEnqueueBuffer(queue, buffer, 0, NULL);
        return (long long)buf->length;
    }
    _spec_emit_str_error(on_error, "Audio error: Failed to allocate AudioToolbox buffer");
    return -1;
#endif
    _spec_emit_str_error(on_error, "Audio error: Unsupported audio backend");
    return -1;
}

long long spec_audio_write(long long handle, SpecByteBuffer* buf) {
    return spec_audio_write_cb(handle, buf, NULL);
}

long long spec_audio_drain(long long handle) {
    long long idx = handle - 1;
    if (idx < 0 || idx >= 8 || !_spec_audio_streams[idx].active) return 0;
#if defined(__linux__)
    if (_spec_snd_pcm_drain) _spec_snd_pcm_drain((spec_snd_pcm_t*)_spec_audio_streams[idx].alsa_handle);
#elif defined(_WIN32)
    Sleep(50);
#elif defined(__APPLE__) && defined(__MACH__)
    if (_spec_AudioQueueStop) _spec_AudioQueueStop(_spec_audio_streams[idx].aq_queue, false);
    if (_spec_AudioQueueStart) _spec_AudioQueueStart(_spec_audio_streams[idx].aq_queue, NULL);
#endif
    return 0;
}

void spec_audio_close(long long handle) {
    long long idx = handle - 1;
    if (idx < 0 || idx >= 8 || !_spec_audio_streams[idx].active) return;
#if defined(__linux__)
    if (_spec_snd_pcm_close) _spec_snd_pcm_close((spec_snd_pcm_t*)_spec_audio_streams[idx].alsa_handle);
#elif defined(_WIN32)
    if (_spec_waveOutReset) _spec_waveOutReset(_spec_audio_streams[idx].h_wave_out);
    if (_spec_waveOutClose) _spec_waveOutClose(_spec_audio_streams[idx].h_wave_out);
#elif defined(__APPLE__) && defined(__MACH__)
    if (_spec_AudioQueueDispose) _spec_AudioQueueDispose(_spec_audio_streams[idx].aq_queue, true);
#endif
    memset(&_spec_audio_streams[idx], 0, sizeof(SpecAudioStream));
}

void spec_process_exit(long long status) {
    exit((int)status);
}

